const { favoriteLayout } = options.getState();
const isDefaultLayout = favoriteLayout.startsWith('searchview.commandbar.layouts.');
if (isDefaultLayout) {
	return { disabled: true };
}

const gridLayoutFavorites = options.getProps().favorites;
const currentLayoutData = gridLayoutFavorites[favoriteLayout];
const currentUserIdentityId = aras.getIsAliasIdentityIDForLoggedUser();
return {
	disabled: currentLayoutData.ownedBy !== currentUserIdentityId
};
